// Actions-only authenticated strict manual nonUID position endpoint; no raw grants.
#[tokio::test]async fn manual_recipient_http_requires_auth_and_exact_intent_fields_no_uid_token_box_reply(){let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-read-status-targets/1/set/recipient";let(status,_,body)=account_request(&served,reqwest::Method::POST,path,None,None).await;assert_eq!(status,StatusCode::UNAUTHORIZED);no_secrets(&body);let cookie=authenticate(&served).await;for key in ["uid","box_id","token","reply","span_hash","scope_epoch","accepted"]{let mut data=serde_json::json!({"expected_revision":1,"expected_index":"7","nonce":"a".repeat(32),"recipient":"[phone:+12345@fixture.invalid]","consent":true});data[key]=serde_json::json!("fixture-private");let(status,headers,body)=account_request(&served,reqwest::Method::POST,path,Some(data),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}}
#[tokio::test]async fn manual_recipient_http_rejects_uid_local_naked_url_overflow_and_noncanonical_ids(){let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let base="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/im-read-status-targets";for recipient in ["1_2","[uid:1_2]","12345","scheme://fixture.invalid"]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/1/set/recipient"),Some(serde_json::json!({"expected_revision":1,"expected_index":"7","nonce":"a".repeat(32),"recipient":recipient,"consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}for(id,index)in[("01","7"),("-1","7"),("1","07"),("1","9223372036854775808")]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("{base}/{id}/set/recipient"),Some(serde_json::json!({"expected_revision":1,"expected_index":index,"nonce":"a".repeat(32),"recipient":"[phone:+12345@fixture.invalid]","consent":true})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);}}
#[tokio::test]async fn manual_recipient_http_saved_configuration_is_not_current_span_auth_or_installed_grant(){let state=build_test_router().await.expect("Actions private bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let mut config=im_runtime_config_json(&cert.root);config["profile"]["im_sync"]=serde_json::json!({"receive":true});config["profile"]["im_read_status"]=serde_json::json!({"set_read_status":true});let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":config})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);for(revision,consent,want)in[(1,false,StatusCode::FORBIDDEN),(2,true,StatusCode::CONFLICT),(1,true,StatusCode::SERVICE_UNAVAILABLE)]{let(status,headers,body)=account_request(&served,reqwest::Method::POST,&format!("/api/non-3gpp/accounts/{line}/im-read-status-targets/1/set/recipient"),Some(serde_json::json!({"expected_revision":revision,"expected_index":"7","nonce":"a".repeat(32),"recipient":"[phone:+12345@fixture.invalid]","consent":consent})),Some(&cookie)).await;assert_eq!(status,want);no_store(&headers);no_secrets(&body);}let view=state.app.app_accounts.get(&line,100).await.unwrap();assert!(view.im_read_status_recipient_supported.is_none());assert_eq!(view.phase,"stopped");assert!(!view.incoming_message_ready&&!view.incoming_call_ready&&!view.outbound_authorized);}
